// Plain (non-"use server") module: shared types for the in-portal file manager.
// A "use server" file may ONLY export async functions — exporting the FileEntry
// type from lib/actions-files.ts triggered Next's
// "A 'use server' file can only export async functions, found object" error when
// the Files tab invoked a server action, so the type lives here and is imported
// (as a type) by both the server actions and the FileManager client component.

export type FileEntry = {
  name: string;
  isDirectory: boolean;
  size: number;
  modifiedMs: number;
  /** Octal permission string like "755", or null if unknown. */
  mode: string | null;
};

// ---------------------------------------------------------------------------
// The file-manager data source.
//
// One file manager, two backends: a VPS reached over SSH/SFTP as root, and a
// shared-hosting account reached over chrooted SFTP as the jailed account user.
// Rather than branching inside the component on which one it is talking to,
// FileBrowser takes a FileApi and calls only that. Paths handed to a FileApi are
// always the browser's own "/"-rooted virtual paths; each adapter translates
// them to whatever its backend wants.
//
// Optional members are the honest part: a source that cannot chmod simply omits
// `chmod`, and the UI does not render a control that cannot work.

export type FileMut = { ok: true } | { ok: false; error: string };
export type FileApi = {
  /** Stable identity for this source — used as a React remount key. */
  key: string;
  /** Label shown as the root breadcrumb, e.g. "root" or "public_html". */
  rootLabel: string;
  list(path: string): Promise<{ ok: true; entries: FileEntry[] } | { ok: false; error: string }>;
  read(path: string): Promise<{ ok: true; content: string } | { ok: false; error: string }>;
  save(path: string, content: string): Promise<FileMut>;
  mkdir(dir: string, name: string): Promise<FileMut>;
  rename(path: string, newName: string): Promise<FileMut>;
  remove(path: string, isDirectory: boolean): Promise<FileMut>;
  /** URL accepting a multipart POST with field `file`; used by the XHR upload queue. */
  uploadUrl(dir: string): string;
  /** True when the upload route accepts `relPath`/`mkdir` (folder uploads with sub-directories). */
  supportsFolders?: boolean;
  /** A direct download URL for one file, or null when the source has no download route. */
  downloadUrl?(path: string): string | null;
  /** Optional chmod; omit when the source cannot change modes. */
  chmod?(path: string, mode: string): Promise<FileMut>;
};
