"use client";

import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { fmtBytes } from "@/components/ui/primitives";
import { UploadQueue, useUploadQueue } from "./UploadQueue";
import { collectDrop, flattenFileList } from "@/lib/upload-paths";
import { serverFileApi } from "@/lib/files-adapters";
import type { FileApi, FileEntry } from "@/lib/files-types";

/**
 * A file manager, rather than a directory listing.
 *
 * What this replaces showed one flat list of the current directory with a
 * Rename and a Delete per row: no folder tree, no search, no multi-select, no
 * sorting, and an editor that opened as a modal over the top of everything.
 * The concept's Files screen is a three-pane browser, and every piece of it is
 * backed by an action that already existed.
 *
 * ONE BROWSER, TWO BACKENDS. This used to take a VPS `serverId` and call the
 * lib/actions-files server actions directly. It now takes a {@link FileApi} — a
 * data source — because the same screen has to drive two genuinely different
 * things: a customer's own VPS over SSH/SFTP as root (absolute paths on the box)
 * and a shared-hosting account over chrooted SFTP as the jailed account user
 * (paths relative to a docroot). Branching on "which product is this" inside a
 * component this size is how both versions drift; the adapters in
 * lib/files-adapters.ts absorb the difference instead, and everything below
 * works in this browser's own "/"-rooted virtual paths.
 *
 * The adapter also says what its source CANNOT do, and the controls that depend
 * on a capability are only rendered when it exists: the row Download link
 * appears only when `api.downloadUrl` is there. (`api.chmod` is optional for the
 * same reason — shared hosting has no chmod primitive — though this browser has
 * never rendered a permissions control for either backend.)
 *
 * DELIBERATELY ABSENT: move and copy. `rename` renames within the SAME parent by
 * design on both backends, and there is no action that relocates a path — so a
 * Move button would be a button that cannot work. Bulk delete is real (it is N
 * deletes) and is offered; bulk move is not.
 */

const EDITABLE = /\.(txt|log|json|ya?ml|toml|ini|cfg|conf|properties|sh|bat|md|env|xml|js|ts|css|html|lock|gitignore)$/i;
const MAX_EDIT_BYTES = 1024 * 1024;

function isEditable(e: FileEntry): boolean {
  return !e.isDirectory && (EDITABLE.test(e.name) || !e.name.includes(".")) && e.size <= MAX_EDIT_BYTES;
}

function joinPath(dir: string, name: string): string {
  return dir === "/" ? `/${name}` : `${dir}/${name}`;
}

function parentOf(p: string): string {
  if (p === "/" || !p.includes("/")) return "/";
  const up = p.slice(0, p.lastIndexOf("/"));
  return up === "" ? "/" : up;
}

function when(ms: number): string {
  return new Date(ms).toLocaleString("en-US", {
    year: "numeric", month: "short", day: "numeric", hour: "2-digit", minute: "2-digit",
  });
}

/* ── folder tree ───────────────────────────────────────────────────────────
   Lazily loaded: a node fetches its children the first time it is opened, so
   opening the browser costs exactly one directory read, not a walk of the
   whole disk. */
function TreeNode({
  api, path, label, depth, current, onOpen,
}: {
  api: FileApi; path: string; label: string; depth: number; current: string; onOpen: (p: string) => void;
}) {
  const [open, setOpen] = useState(depth === 0);
  const [kids, setKids] = useState<FileEntry[] | null>(null);
  const [loading, setLoading] = useState(false);

  const apiRef = useRef(api);
  apiRef.current = api;

  const load = useCallback(async () => {
    if (kids || loading) return;
    setLoading(true);
    const res = await apiRef.current.list(path).catch(() => null);
    setKids(res && res.ok ? res.entries.filter((e) => e.isDirectory && !e.name.startsWith(".")) : []);
    setLoading(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- api is read through a ref; `key` is its identity
  }, [api.key, path, kids, loading]);

  useEffect(() => { if (open) void load(); }, [open, load]);

  const active = current === path;

  return (
    <div>
      <div
        className={"flex items-center gap-1 rounded-[8px] py-1 pr-2 transition " +
          (active ? "bg-[#7b3fef]/22 text-white" : "text-tx-dim hover:bg-white/[0.04] hover:text-white")}
        style={{ paddingLeft: 4 + depth * 12 }}
      >
        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          aria-label={open ? `Collapse ${label}` : `Expand ${label}`}
          className="grid h-[16px] w-[16px] flex-none place-items-center text-tx-faint transition hover:text-white"
        >
          <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3.4"
               strokeLinecap="round" strokeLinejoin="round"
               className={"transition-transform " + (open ? "rotate-90" : "")}>
            <path d="m9 6 6 6-6 6" />
          </svg>
        </button>
        <button type="button" onClick={() => onOpen(path)} className="flex min-w-0 flex-1 items-center gap-1.5 text-left">
          <Icon name="folder" size={12} tone="inherit" className="flex-none text-[#7fb0ff]" />
          <span className="truncate text-[12px] font-medium">{label}</span>
        </button>
      </div>
      {open && (
        <div>
          {loading && <p className="py-1 text-[11px] text-tx-faint" style={{ paddingLeft: 22 + depth * 12 }}>…</p>}
          {kids?.map((k) => (
            <TreeNode key={k.name} api={api} path={joinPath(path, k.name)} label={k.name}
                      depth={depth + 1} current={current} onOpen={onOpen} />
          ))}
        </div>
      )}
    </div>
  );
}

export function FileBrowser({ api, initialPath = "/" }: { api: FileApi; initialPath?: string }) {
  const [path, setPath] = useState(initialPath);
  const [entries, setEntries] = useState<FileEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [q, setQ] = useState("");
  const [sort, setSort] = useState<"name" | "size" | "modified">("name");
  const [selected, setSelected] = useState<string[]>([]);
  const [dragOver, setDragOver] = useState(false);
  const [pending, start] = useTransition();
  const inputRef = useRef<HTMLInputElement | null>(null);

  const [editor, setEditor] = useState<{ path: string; content: string; dirty: boolean } | null>(null);
  const [editorBusy, setEditorBusy] = useState(false);

  const flash = (m: string) => { setNotice(m); setTimeout(() => setNotice(null), 3500); };

  // A caller may well build its adapter inline, handing us a fresh object every
  // render. `key` is the source's stable identity, so callbacks depend on that
  // and read the live adapter through a ref — depending on the object itself
  // would restart the directory read on every render, forever.
  const apiRef = useRef(api);
  apiRef.current = api;

  const refresh = useCallback(async () => {
    setLoading(true);
    const res = await apiRef.current.list(path).catch(() => null);
    if (!res) setError("Couldn't reach the server.");
    else if (!res.ok) setError(res.error);
    else { setEntries(res.entries); setError(null); }
    setSelected([]);
    setLoading(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- api is read through a ref; `key` is its identity
  }, [api.key, path]);

  useEffect(() => { void refresh(); }, [refresh]);

  const onUploadNotice = useCallback((m: string) => setError(m), []);
  const upload = useUploadQueue(api, path, () => { void refresh(); }, onUploadNotice);
  const folderInputRef = useRef<HTMLInputElement | null>(null);

  const shown = useMemo(() => {
    const needle = q.trim().toLowerCase();
    const rows = entries.filter((e) => !needle || e.name.toLowerCase().includes(needle));
    return [...rows].sort((a, b) => {
      // Folders always lead, whatever the sort — that is what makes a listing
      // navigable rather than just ordered.
      if (a.isDirectory !== b.isDirectory) return a.isDirectory ? -1 : 1;
      if (sort === "size") return b.size - a.size;
      if (sort === "modified") return b.modifiedMs - a.modifiedMs;
      return a.name.localeCompare(b.name);
    });
  }, [entries, q, sort]);

  const crumbs = useMemo(() => {
    const parts = path.split("/").filter(Boolean);
    return [{ label: api.rootLabel, path: "/" }, ...parts.map((p, i) => ({ label: p, path: "/" + parts.slice(0, i + 1).join("/") }))];
  }, [path, api.rootLabel]);

  const openEntry = (e: FileEntry) => {
    if (e.isDirectory) { setPath(joinPath(path, e.name)); setEditor(null); return; }
    if (!isEditable(e)) return;
    const full = joinPath(path, e.name);
    setEditorBusy(true);
    start(async () => {
      const res = await apiRef.current.read(full).catch(() => null);
      setEditorBusy(false);
      if (!res || !res.ok) { setError(res && !res.ok ? res.error : "Couldn't open that file."); return; }
      setEditor({ path: full, content: res.content, dirty: false });
    });
  };

  const save = () => {
    if (!editor) return;
    setEditorBusy(true);
    start(async () => {
      const res = await apiRef.current.save(editor.path, editor.content).catch(() => null);
      setEditorBusy(false);
      if (!res || !res.ok) { setError(res && !res.ok ? res.error : "Couldn't save."); return; }
      setEditor({ ...editor, dirty: false });
      flash("Saved.");
      void refresh();
    });
  };

  type Mut = { ok: true } | { ok: false; error: string };
  const mutate = (fn: () => Promise<Mut>, done: string) =>
    start(async () => {
      setError(null);
      const res = await fn().catch((): Mut => ({ ok: false, error: "Couldn't reach the server." }));
      if (!res.ok) { setError(res.error); return; }
      flash(done);
      void refresh();
    });

  const removeSelected = () => {
    if (!selected.length) return;
    if (!window.confirm(`Delete ${selected.length} item${selected.length === 1 ? "" : "s"}? This cannot be undone.`)) return;
    start(async () => {
      setError(null);
      let failed = 0;
      for (const name of selected) {
        const row = entries.find((e) => e.name === name);
        const res = await apiRef.current
          .remove(joinPath(path, name), row?.isDirectory ?? false)
          .catch(() => null);
        if (!res || !res.ok) failed++;
      }
      if (failed) setError(`${failed} item${failed === 1 ? "" : "s"} couldn't be deleted.`);
      else flash(`Deleted ${selected.length} item${selected.length === 1 ? "" : "s"}.`);
      void refresh();
    });
  };

  const busy = pending || loading;

  return (
    <div className="flex flex-col gap-3">
      {/* ── toolbar ──────────────────────────────────────────────────────── */}
      <div className="flex flex-wrap items-center gap-2.5 rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3.5 py-2.5">
        <nav className="flex min-w-0 flex-1 items-center gap-1 overflow-x-auto text-[12.5px]">
          {crumbs.map((c, i) => (
            <span key={c.path} className="flex flex-none items-center gap-1">
              {i > 0 && <span className="text-tx-faint">/</span>}
              <button type="button" onClick={() => { setPath(c.path); setEditor(null); }}
                      className={"rounded-[7px] px-1.5 py-0.5 font-mono transition " +
                        (i === crumbs.length - 1 ? "text-white" : "text-tx-dim hover:text-white")}>
                {c.label}
              </button>
            </span>
          ))}
        </nav>

        <span className="flex h-[34px] w-[190px] flex-none items-center gap-2 rounded-[9px] border border-rim-hi bg-well px-3">
          <Icon name="search" size={13} tone="inherit" className="flex-none text-tx-faint" />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search this folder…"
                 className="min-w-0 flex-1 bg-transparent text-[12px] text-white outline-none placeholder:text-tx-faint" />
        </span>

        <button type="button" onClick={() => inputRef.current?.click()} disabled={upload.busy}
                className="nx-cta flex-none px-3.5 py-1.5 text-[12.5px] disabled:opacity-60">
          <Icon name="upload" size={13} tone="inherit" /> {upload.busy ? "Uploading…" : "Upload"}
        </button>
        {api.supportsFolders && (
          <button type="button" onClick={() => folderInputRef.current?.click()} disabled={upload.busy}
                  className="flex-none rounded-[9px] border border-rim-hi bg-well px-3.5 py-1.5 text-[12.5px] font-semibold text-tx-dim transition hover:text-white disabled:opacity-60">
            Upload folder
          </button>
        )}
        <button type="button" disabled={busy}
                onClick={() => {
                  const name = window.prompt("New folder name:");
                  if (name) mutate(() => apiRef.current.mkdir(path, name), "Folder created.");
                }}
                className="flex-none rounded-[9px] border border-rim-hi bg-well px-3.5 py-1.5 text-[12.5px] font-semibold text-tx-dim transition hover:text-white disabled:opacity-60">
          New folder
        </button>
        <button type="button" onClick={() => void refresh()} disabled={busy} aria-label="Refresh"
                className="grid h-[32px] w-[32px] flex-none place-items-center rounded-[9px] border border-rim-hi text-tx-faint transition hover:text-white disabled:opacity-60">
          <Icon name="refresh" size={13} tone="inherit" />
        </button>
        <input ref={inputRef} type="file" multiple className="hidden"
               onChange={(e) => { if (e.target.files?.length) { const r = flattenFileList(e.target.files); upload.enqueue(r.entries, r.error); } e.target.value = ""; }} />
        {/* webkitdirectory is non-standard but supported by every current browser; React needs it spread as an attribute */}
        <input ref={folderInputRef} type="file" multiple className="hidden"
               {...({ webkitdirectory: "", directory: "" } as Record<string, string>)}
               onChange={(e) => {
                 if (e.target.files?.length) { const r = flattenFileList(e.target.files); upload.enqueue(r.entries, r.error); }
                 e.target.value = "";
               }} />
      </div>

      <UploadQueue items={upload.items} onCancel={upload.cancel} onDismiss={upload.dismiss} onClearDone={upload.clearDone} onRetry={upload.retry} />

      {notice && <p className="rounded-[10px] border border-emerald-500/30 bg-emerald-500/10 px-3.5 py-2 text-[12.5px] text-emerald-300">{notice}</p>}
      {error && <p className="rounded-[10px] border border-red-500/30 bg-red-500/10 px-3.5 py-2 text-[12.5px] text-red-300">{error}</p>}

      {/* ── three panes ──────────────────────────────────────────────────── */}
      <div className={"grid gap-3 " + (editor ? "xl:grid-cols-[210px_minmax(0,1fr)_minmax(0,1.1fr)]" : "xl:grid-cols-[210px_minmax(0,1fr)]")}>
        <aside className="hidden max-h-[560px] min-w-0 overflow-auto rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-2 xl:block">
          <TreeNode api={api} path="/" label={`/ (${api.rootLabel})`} depth={0} current={path} onOpen={(p) => { setPath(p); setEditor(null); }} />
        </aside>

        <section
          onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onDrop={(e) => {
            e.preventDefault(); setDragOver(false);
            if (!e.dataTransfer.items?.length && !e.dataTransfer.files?.length) return;
            // collectDrop reads webkitGetAsEntry synchronously; the walk finishes async.
            void collectDrop(e.dataTransfer)
              .then((r) => upload.enqueue(r.entries, r.error))
              .catch(() => setError("Couldn't read the dropped items — try the Upload folder button."));
          }}
          className={"flex min-w-0 flex-col overflow-hidden rounded-[14px] border bg-[rgba(6,14,36,.72)] transition " +
            (dragOver ? "border-brand-400 bg-[rgba(72,148,255,.08)]" : "border-rim-hi")}
        >
          <div className="grid grid-cols-[28px_minmax(0,1fr)_44px] sm:grid-cols-[28px_minmax(0,1fr)_90px_150px_36px] items-center gap-2 border-b border-rim-soft px-3.5 py-2 text-[10px] font-bold uppercase tracking-[0.12em] text-tx-faint">
            <span>
              <input
                type="checkbox"
                aria-label="Select all"
                checked={shown.length > 0 && selected.length === shown.length}
                onChange={(e) => setSelected(e.target.checked ? shown.map((s) => s.name) : [])}
                className="h-[13px] w-[13px] accent-[#7b3fef]"
              />
            </span>
            <button type="button" onClick={() => setSort("name")} className="text-left transition hover:text-white">Name</button>
            <button type="button" onClick={() => setSort("size")} className="hidden text-left transition hover:text-white sm:block">Size</button>
            <button type="button" onClick={() => setSort("modified")} className="hidden text-left transition hover:text-white sm:block">Modified</button>
            <span />
          </div>

          <div className="max-h-[520px] min-w-0 overflow-auto">
            {loading ? (
              <p className="px-4 py-8 text-center text-[12.5px] text-tx-faint">Reading {path}…</p>
            ) : shown.length === 0 ? (
              <p className="px-4 py-10 text-center text-[12.5px] text-tx-faint">
                {q ? `Nothing here matches “${q}”.` : "This folder is empty. Drop files anywhere on this panel to upload."}
              </p>
            ) : (
              <>
                {path !== "/" && (
                  <button type="button" onClick={() => { setPath(parentOf(path)); setEditor(null); }}
                          className="grid w-full grid-cols-[28px_minmax(0,1fr)] items-center gap-2 px-3.5 py-2 text-left transition hover:bg-white/[0.04]">
                    <span />
                    <span className="flex items-center gap-2 text-[12.5px] text-tx-dim">
                      <Icon name="folder" size={14} tone="inherit" className="text-tx-faint" /> ..
                    </span>
                  </button>
                )}
                {shown.map((e) => {
                  const full = joinPath(path, e.name);
                  const open = editor?.path === full;
                  const canEdit = isEditable(e);
                  return (
                    <div key={e.name}
                         className={"group grid grid-cols-[28px_minmax(0,1fr)_44px] sm:grid-cols-[28px_minmax(0,1fr)_90px_150px_36px] items-center gap-2 border-b border-rim-soft/50 px-3.5 py-2 transition last:border-0 " +
                           (open ? "bg-[#7b3fef]/15" : "hover:bg-white/[0.04]")}>
                      <input
                        type="checkbox"
                        aria-label={`Select ${e.name}`}
                        checked={selected.includes(e.name)}
                        onChange={(ev) => setSelected((s) => ev.target.checked ? [...s, e.name] : s.filter((n) => n !== e.name))}
                        className="h-[13px] w-[13px] accent-[#7b3fef]"
                      />
                      <button type="button" onClick={() => openEntry(e)} disabled={!e.isDirectory && !canEdit}
                              className="flex min-w-0 items-center gap-2 text-left disabled:cursor-default">
                        <Icon name={e.isDirectory ? "folder" : "file"} size={14} tone="inherit"
                              className={"flex-none " + (e.isDirectory ? "text-[#7fb0ff]" : "text-tx-faint")} />
                        <span className={"truncate text-[12.5px] " + (e.isDirectory ? "font-semibold text-white" : canEdit ? "text-white" : "text-tx-dim")}>
                          {e.name}
                        </span>
                        {!e.isDirectory && <span className="ml-auto flex-none pl-1 text-[10.5px] text-tx-faint sm:hidden">{fmtBytes(e.size)}</span>}
                      </button>
                      <span className="hidden text-[11.5px] text-tx-faint sm:block">{e.isDirectory ? "—" : fmtBytes(e.size)}</span>
                      <span className="hidden truncate text-[11.5px] text-tx-faint sm:block">{when(e.modifiedMs)}</span>
                      <RowMenu
                        onRename={() => {
                          const name = window.prompt("Rename to:", e.name);
                          if (name && name !== e.name) mutate(() => apiRef.current.rename(full, name), "Renamed.");
                        }}
                        onDelete={() => {
                          if (window.confirm(`Delete ${e.name}? This cannot be undone.`)) mutate(() => apiRef.current.remove(full, e.isDirectory), "Deleted.");
                        }}
                        downloadHref={e.isDirectory ? null : (api.downloadUrl?.(full) ?? null)}
                      />
                    </div>
                  );
                })}
              </>
            )}
          </div>

          {selected.length > 0 && (
            <div className="flex flex-wrap items-center gap-2.5 border-t border-rim-soft bg-[rgba(3,9,24,.7)] px-3.5 py-2.5">
              <span className="text-[12px] font-semibold text-white">{selected.length} selected</span>
              <button type="button" onClick={removeSelected} disabled={busy}
                      className="ml-auto rounded-[9px] border border-red-500/45 px-3 py-1.5 text-[12px] font-semibold text-red-300 transition hover:bg-red-500/10 disabled:opacity-60">
                Delete
              </button>
              <button type="button" onClick={() => setSelected([])}
                      className="rounded-[9px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-white">
                Clear
              </button>
            </div>
          )}
        </section>

        {editor && (
          <section className="flex min-w-0 flex-col overflow-hidden rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)]">
            <div className="flex items-center gap-2.5 border-b border-rim-soft px-3.5 py-2.5">
              <Icon name="file" size={14} className="flex-none" />
              <span className="min-w-0 flex-1 truncate font-mono text-[12px] text-white">{editor.path}</span>
              {editor.dirty && <span className="flex-none text-[11px] font-semibold text-amber-300">Unsaved</span>}
              <button type="button" onClick={save} disabled={editorBusy || !editor.dirty}
                      className="nx-cta flex-none px-3 py-1.5 text-[12px] disabled:opacity-50">
                {editorBusy ? "Saving…" : "Save"}
              </button>
              <button type="button" onClick={() => setEditor(null)} aria-label="Close editor"
                      className="flex-none text-tx-faint transition hover:text-white">
                <Icon name="xcircle" size={15} tone="inherit" />
              </button>
            </div>
            <textarea
              value={editor.content}
              onChange={(e) => setEditor({ ...editor, content: e.target.value, dirty: true })}
              spellCheck={false}
              className="min-h-[460px] flex-1 resize-none bg-[rgba(3,9,24,.86)] p-3.5 font-mono text-[12px] leading-[1.7] text-tx-dim outline-none"
            />
          </section>
        )}
      </div>

      <p className="text-[11.5px] leading-relaxed text-tx-faint">
        Text files up to 1&nbsp;MB open in the editor. Anything else can be downloaded, replaced by
        uploading over it, or renamed and deleted here.
      </p>
    </div>
  );
}

/**
 * The VPS file manager, for callers that only have a server id.
 *
 * The server-side pages that render the Files tab are React Server Components,
 * and a FileApi is an object of FUNCTIONS — it cannot cross the RSC boundary as
 * a prop. So the adapter is built HERE, on the client, from the one serializable
 * thing the page does have. `useMemo` keeps its identity stable across renders.
 */
export function ServerFileBrowser({ serverId, initialPath }: { serverId: string; initialPath?: string }) {
  const api = useMemo(() => serverFileApi(serverId), [serverId]);
  return <FileBrowser key={api.key} api={api} initialPath={initialPath} />;
}

function RowMenu({ onRename, onDelete, downloadHref }: {
  onRename: () => void; onDelete: () => void; downloadHref: string | null;
}) {
  const [open, setOpen] = useState(false);
  return (
    <span className="relative justify-self-end">
      <button type="button" onClick={() => setOpen((v) => !v)} onBlur={() => setTimeout(() => setOpen(false), 140)}
              aria-label="More actions"
              className="grid h-[26px] w-[26px] place-items-center rounded-[7px] text-tx-faint opacity-0 transition hover:bg-white/[0.06] hover:text-white group-hover:opacity-100">
        <Icon name="ellipsis" size={14} tone="inherit" />
      </button>
      {open && (
        <span className="absolute right-0 top-[30px] z-30 flex w-[160px] flex-col overflow-hidden rounded-[10px] border border-rim-hi bg-surface py-1 shadow-2xl">
          {downloadHref && (
            <a href={downloadHref} className="px-3 py-1.5 text-[12px] text-tx-dim hover:bg-white/[0.05] hover:text-white">Download</a>
          )}
          <button type="button" onMouseDown={(e) => { e.preventDefault(); onRename(); setOpen(false); }}
                  className="px-3 py-1.5 text-left text-[12px] text-tx-dim hover:bg-white/[0.05] hover:text-white">Rename</button>
          <button type="button" onMouseDown={(e) => { e.preventDefault(); onDelete(); setOpen(false); }}
                  className="px-3 py-1.5 text-left text-[12px] text-red-300 hover:bg-red-500/10">Delete</button>
        </span>
      )}
    </span>
  );
}

// Client-side FileApi factories — the adapters that let ONE file manager drive
// two different backends.
//
// A VPS is reached over SSH/SFTP as root and thinks in absolute paths; a
// shared-hosting account is reached over chrooted SFTP as the jailed account
// user and thinks in paths relative to its own jail. FileBrowser knows about
// neither: it works in its own "/"-rooted virtual paths and calls a FileApi,
// and the translation lives here, one small function per source.
//
// This is a plain module, NOT "use server": it is imported from client
// components, and the server actions it closes over become client references
// when bundled. Keeping it separate from lib/files-types.ts matters for the same
// reason that file explains — a "use server" file may only export async
// functions, so neither the types nor these factories can live in one.

import {
  listFiles,
  readFile,
  saveFile,
  createFolder,
  renameEntry,
  deleteEntry,
  chmodEntry,
} from "./actions-files";
import {
  hostingFsList,
  hostingFsRead,
  hostingFsSave,
  hostingFsMkdir,
  hostingFsRename,
  hostingFsDelete,
} from "./actions-hosting-fs";
import type { FileApi } from "./files-types";

/**
 * A customer's own VPS, over the actions in lib/actions-files.ts. Paths are
 * already absolute "/"-rooted paths on the box, so no translation is needed —
 * the browser's virtual root IS the server's root.
 */
export function serverFileApi(serverId: string): FileApi {
  return {
    key: `server:${serverId}`,
    rootLabel: "root",
    async list(path) {
      const res = await listFiles(serverId, path);
      return res.ok ? { ok: true, entries: res.entries } : { ok: false, error: res.error };
    },
    async read(path) {
      const res = await readFile(serverId, path);
      return res.ok ? { ok: true, content: res.content } : { ok: false, error: res.error };
    },
    save: (path, content) => saveFile(serverId, path, content),
    mkdir: (dir, name) => createFolder(serverId, dir, name),
    rename: (path, newName) => renameEntry(serverId, path, newName),
    // `deleteEntry` stats the path itself and picks rmdir vs unlink, so it takes
    // no isDirectory — the argument is accepted and ignored here on purpose.
    remove: (path) => deleteEntry(serverId, path),
    uploadUrl: (dir) => `/api/files/${serverId}?path=${encodeURIComponent(dir)}`,
    supportsFolders: true,
    downloadUrl: (path) => `/api/files/${serverId}?path=${encodeURIComponent(path)}&download=1`,
    chmod: (path, mode) => chmodEntry(serverId, path, mode),
  };
}

/** Strip the leading/trailing slashes and collapse the empties out of a path. */
function segments(p: string): string[] {
  return String(p ?? "").split("/").filter(Boolean);
}

/**
 * A shared-hosting account, over the actions in lib/actions-hosting-fs.ts.
 *
 * `root` is a chroot-relative base — "public_html", "domains/example.com/public_html",
 * or "" for the whole account home. The browser's "/" is that base, so "/a/b"
 * becomes "<root>/a/b" and a customer can never navigate above the docroot they
 * were given even before the OS chroot has an opinion.
 *
 * NOTE: the account home maps to "." rather than the empty string, because
 * lib/hosting-fs's `safeRel` turns an empty path into "public_html" — which
 * would silently drop a browser rooted at the home directory into the docroot
 * instead. "." is the same directory the chrooted session starts in.
 */
export function hostingFileApi(accountId: string, root: string): FileApi {
  const base = segments(root);
  const rel = (path: string) => [...base, ...segments(path)].join("/") || ".";
  const q = (path: string) =>
    `/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(rel(path))}`;

  return {
    key: `hosting:${accountId}:${root}`,
    rootLabel: base.length ? base[base.length - 1] : "home",
    list: (path) => hostingFsList(accountId, rel(path)),
    read: (path) => hostingFsRead(accountId, rel(path)),
    save: (path, content) => hostingFsSave(accountId, rel(path), content),
    mkdir: (dir, name) => hostingFsMkdir(accountId, rel(dir), name),
    rename: (path, newName) => hostingFsRename(accountId, rel(path), newName),
    remove: (path, isDirectory) => hostingFsDelete(accountId, rel(path), isDirectory),
    uploadUrl: (dir) => q(dir),
    downloadUrl: (path) => q(path),
    // No chmod: the hosting backend has no chmod primitive, so the browser must
    // not offer a control that cannot work.
  };
}
/**
 * Server-side SFTP proxy for the in-portal file manager.
 *
 * This is a plain (non-"use server") module so it can be imported by both the
 * server actions (lib/actions-files.ts) and the upload/download route handler.
 * It never runs in the browser — the customer's root credentials stay on the
 * server; the browser only ever talks to our own actions/route.
 *
 * Connection target is derived EXACTLY like the server detail page:
 *   - dedicated-IP servers connect to their own IP on port 22
 *   - NAT servers use PUBLIC_IP + the forwarded SSH port
 * Username is always "root"; password is `server.rootPassword`.
 *
 * SANDBOX: on staging (NXEON_SANDBOX=1) no real SSH connection is ever opened —
 * every op is backed by a small in-memory simulated filesystem so the whole
 * file-manager UX works end to end without a live VM.
 */
import SftpClient from "ssh2-sftp-client";
import { SANDBOX } from "./sandbox";
import { decryptSecret } from "./crypto-box";

/**
 * Resolve a server's plaintext root password, preferring the encrypted-at-rest
 * value and falling back to the legacy plaintext column for rows that predate
 * encryption. Every READ of a root password must go through this helper so both
 * shapes keep working transparently.
 */
export function serverRootPassword(
  server: { rootPassword: string | null; rootPasswordEnc?: string | null }
): string | null {
  return decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
}

/**
 * Resolve a server's decrypted OpenSSH-format management PRIVATE key, if one has
 * been generated for it (see Server.sshManagementKeyEnc's schema doc comment).
 * Null for any server not yet provisioned/backfilled with one.
 */
export function serverManagementKey(
  server: { sshManagementKeyEnc?: string | null }
): string | null {
  return decryptSecret(server.sshManagementKeyEnc);
}

/** The minimal shape of a Server we need to open a connection. */
export type SftpServer = {
  id: string;
  rootPassword: string | null;
  rootPasswordEnc?: string | null;
  /** See Server.sshManagementKeyEnc's schema doc comment. Optional so every
   *  existing caller that doesn't select it keeps today's password-only path. */
  sshManagementKeyEnc?: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
  /** The server's own node — vmids/ports are per-node, so a NAT (non-dedicated-IP)
   *  server's real SSH host is THIS node's public IP, not necessarily the
   *  platform's env-configured primary. Optional so existing callers that don't
   *  select it keep today's exact fallback behavior (see connectionTarget). */
  node?: { publicIp: string } | null;
  /** See Server.guestSshPort's schema doc comment. Only meaningful on a
   *  dedicated-IP server — optional so a caller that doesn't select it keeps
   *  today's "assume port 22" behavior via connectionTarget's `?? 22`. */
  guestSshPort?: number | null;
};

export type SftpEntry = {
  name: string;
  /** "d" directory, "-" file, "l" symlink, etc. (ssh2-sftp-client `type`). */
  type: string;
  isDirectory: boolean;
  size: number;
  /** Unix mtime in ms. */
  modifiedMs: number;
  /** Numeric permission bits (e.g. 0o644), or null if unknown. */
  mode: number | null;
};

export type SftpStat = {
  isDirectory: boolean;
  size: number;
  modifiedMs: number;
  mode: number | null;
};

const CONNECT_TIMEOUT_MS = 10_000;

/** Max length for any absolute path we accept from the client. */
export const MAX_PATH_LEN = 4096;
/** Max length for a single path segment (file/folder name). */
export const MAX_NAME_LEN = 255;

/**
 * Normalize + validate an absolute POSIX path coming from the browser. Rejects
 * relative paths, `..` traversal, NUL bytes, and over-long paths. Returns a
 * cleaned absolute path (collapsed slashes, resolved `.`), always starting with
 * "/". Throws on anything suspicious — callers surface the message.
 */
export function normalizePath(input: string): string {
  if (typeof input !== "string") throw new Error("Invalid path.");
  if (input.length > MAX_PATH_LEN) throw new Error("Path is too long.");
  if (input.includes("\0")) throw new Error("Invalid path.");
  if (!input.startsWith("/")) throw new Error("Path must be absolute.");

  const out: string[] = [];
  for (const part of input.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === "..") throw new Error("Path traversal is not allowed.");
    if (part.length > MAX_NAME_LEN) throw new Error("A path segment is too long.");
    out.push(part);
  }
  return "/" + out.join("/");
}

/**
 * Validate a single new file/folder name — no slashes, no traversal, no NUL,
 * not "." or "..". Returns the name unchanged if valid.
 */
