/**
 * Archive extraction for the customer file manager — the PURE parts.
 *
 * Plain module (no "use server", no I/O) so it can be unit-tested and so the
 * guest-side shell script can be exercised against real archives in a temp dir.
 * The server action that drives it lives in lib/actions-files.ts.
 *
 * THREAT MODEL. The archive is untrusted input (a customer downloads mods from
 * the internet), and extraction runs as root on the customer's own VM — the same
 * privilege the file manager already has over SFTP. We must therefore make sure
 * an archive can only ever create files INSIDE the chosen folder, can't plant
 * links/devices that point elsewhere, and can't fill the disk or run forever.
 * Defence is layered:
 *   1. LIST first (unzip -Z -l / tar -tv / bsdtar -tv) and refuse on: zip-slip
 *      names, absolute paths, hard links, device/fifo entries, symlinks that
 *      escape (or any symlink in a .zip, whose target the listing cannot show),
 *      entries written THROUGH a symlink, too many files, too many bytes, an
 *      absurd compression ratio, or not enough free disk.
 *   2. EXTRACT into a private staging dir inside the target (never directly into
 *      it) under `timeout`, `ulimit -f`, with a watchdog that kills the extractor
 *      if the staging dir exceeds the byte/file caps (headers can lie).
 *   3. POST-SCAN the staging dir (the real guard — it does not trust the
 *      listing): delete any non-regular file, any symlink that is absolute or
 *      resolves outside staging, any hard-linked file; strip setuid/setgid.
 *   4. MERGE file-by-file into the target: never follow a symlink or non-dir at a
 *      destination directory, never overwrite unless asked, count what was skipped.
 * Nested archives are NOT recursed into.
 */

export const MAX_EXTRACT_BYTES = 2 * 1024 ** 3; // 2 GiB uncompressed
export const MAX_EXTRACT_FILES = 20_000; // entries (files + dirs + links)
export const EXTRACT_TIMEOUT_S = 300;
/** Free space that must remain after extraction. */
export const MIN_FREE_MARGIN_BYTES = 256 * 1024 ** 2;
/** Refuse ratios above this when the archive would unpack to more than RATIO_MIN_BYTES. */
export const MAX_RATIO = 1000;
export const RATIO_MIN_BYTES = 100 * 1024 ** 2;
/** Cap on listing output we are willing to buffer (a "million tiny files" bomb). */
export const MAX_LISTING_BYTES = 8_000_000;

export type ArchiveKind = "zip" | "tar" | "7z" | "rar";
export type Compression = "gz" | "bz2" | "xz" | null;
export type ArchiveInfo = {
  kind: ArchiveKind;
  compression: Compression;
  /** File name with the archive extension removed — the suggested folder name. */
  stem: string;
};

const TYPE_TABLE: Array<[RegExp, ArchiveKind, Compression]> = [
  [/\.tar\.gz$/i, "tar", "gz"],
  [/\.tgz$/i, "tar", "gz"],
  [/\.tar\.bz2$/i, "tar", "bz2"],
  [/\.tbz2?$/i, "tar", "bz2"],
  [/\.tar\.xz$/i, "tar", "xz"],
  [/\.txz$/i, "tar", "xz"],
  [/\.tar$/i, "tar", null],
  [/\.zip$/i, "zip", null],
  [/\.7z$/i, "7z", null],
  [/\.rar$/i, "rar", null],
];

/** Detect an extractable archive from its file name, or null. */
export function detectArchive(name: string): ArchiveInfo | null {
  if (typeof name !== "string") return null;
  const base = name.slice(name.lastIndexOf("/") + 1);
  for (const [re, kind, compression] of TYPE_TABLE) {
    const m = re.exec(base);
    if (m && m.index > 0) return { kind, compression, stem: base.slice(0, m.index) };
  }
  return null;
}

/** The command family the guest script uses for a kind. */
export function toolFamily(kind: ArchiveKind): "zip" | "tar" | "bsd" {
  return kind === "zip" ? "zip" : kind === "tar" ? "tar" : "bsd";
}

/** Logical tools required on the guest for this archive. */
export function requiredTools(info: ArchiveInfo): string[] {
  const t = ["timeout"];
  if (info.kind === "zip") t.push("unzip");
  else if (info.kind === "tar") {
    t.push("tar");
    if (info.compression === "gz") t.push("gzip");
    if (info.compression === "bz2") t.push("bzip2");
    if (info.compression === "xz") t.push("xz");
  } else t.push("bsdtar");
  return t;
}

/** Package name for a logical tool on a package-manager family. */
export function packageFor(pm: "apt" | "dnf" | "yum", tool: string): string | null {
  switch (tool) {
    case "unzip": return "unzip";
    case "gzip": return "gzip";
    case "bzip2": return "bzip2";
    case "xz": return pm === "apt" ? "xz-utils" : "xz";
    case "bsdtar": return pm === "apt" ? "libarchive-tools" : "bsdtar";
    case "tar": return "tar";
    default: return null; // timeout (coreutils) is not something we install piecemeal
  }
}

export function pmFromPrefix(prefix: string): "apt" | "dnf" | "yum" {
  if (prefix.includes("apt-get")) return "apt";
  if (prefix.startsWith("dnf")) return "dnf";
  return "yum";
}

// ---------------------------------------------------------------------------
// Listing parsers
// ---------------------------------------------------------------------------

export type EntryType = "file" | "dir" | "symlink" | "hardlink" | "special";
export type ArchiveEntry = {
  path: string;
  type: EntryType;
  size: number;
  /** Known for tar/bsdtar symlinks only. */
  linkTarget?: string;
};

function typeFromChar(c: string): EntryType {
  switch (c) {
    case "-": return "file";
    case "d": return "dir";
    case "l": return "symlink";
    case "h": return "hardlink";
    default: return "special"; // c b p s D ...
  }
}

function splitLink(rest: string, type: EntryType): { path: string; linkTarget?: string } {
  if (type === "symlink") {
    const i = rest.indexOf(" -> ");
    if (i >= 0) return { path: rest.slice(0, i), linkTarget: rest.slice(i + 4) };
  }
  if (type === "hardlink") {
    const i = rest.indexOf(" link to ");
    if (i >= 0) return { path: rest.slice(0, i), linkTarget: rest.slice(i + 9) };
  }
  return { path: rest };
}

const NONEMPTY = (l: string) => l.trim().length > 0;

/** `unzip -Z -l` (zipinfo long format). Throws on anything it cannot account for. */
export function parseZipinfo(out: string): ArchiveEntry[] {
  const entries: ArchiveEntry[] = [];
  let declared: number | null = null;
  const re = /^(\S{7,10})\s+(\S+)\s+(\S+)\s+(\d+)\s+(\S{2})\s+(\d+)\s+(\S+)\s+(\d{2}-\w{3}-\d{2}|\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2})\s(.*)$/;
  for (const line of out.split("\n").filter(NONEMPTY)) {
    if (/^Archive:\s/.test(line) || /^Zip file size:/.test(line)) continue;
    const sum = /^(\d+) files?, \d+ bytes uncompressed/.exec(line);
    if (sum) { declared = Number(sum[1]); continue; }
    if (/^Empty zipfile\.?$/.test(line)) { declared = 0; continue; }
    const m = re.exec(line);
    if (!m) throw new Error("Couldn't read this archive's file list (it may be damaged).");
    const type = typeFromChar(m[1][0]);
    entries.push({ path: m[10], type, size: Number(m[4]) });
  }
  if (declared === null || declared !== entries.length) {
    throw new Error("Couldn't read this archive's file list (it may be damaged).");
  }
  return entries;
}

/** GNU `tar -tvf`. */
export function parseGnuTar(out: string): ArchiveEntry[] {
  const re = /^([-dlhcbpsD])\S{9}\s+\S+\s+([\d,]+)\s+(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2}(?::\d{2})?)\s(.*)$/;
  const entries: ArchiveEntry[] = [];
  for (const line of out.split("\n").filter(NONEMPTY)) {
    const m = re.exec(line);
    if (!m) throw new Error("Couldn't read this archive's file list (it may be damaged).");
    const type = typeFromChar(m[1]);
    const { path, linkTarget } = splitLink(m[5], type);
    entries.push({ path, type, size: type === "file" ? Number(m[2].replace(/,.*/, "")) : 0, linkTarget });
  }
  return entries;
}

/** libarchive `bsdtar -tvf` (7z, rar). */
export function parseBsdtar(out: string): ArchiveEntry[] {
  const re = /^([-dlhcbpsD])\S{9}\s+\d+\s+(\S+)\s+(\S+)\s+(\d+)\s+(\w{3})\s+(\d+)\s+(\d{1,2}:\d{2}|\d{4})\s(.*)$/;
  const entries: ArchiveEntry[] = [];
  for (const line of out.split("\n").filter(NONEMPTY)) {
    const m = re.exec(line);
    if (!m) throw new Error("Couldn't read this archive's file list (it may be damaged).");
    const type = typeFromChar(m[1]);
    const { path, linkTarget } = splitLink(m[8], type);
    entries.push({ path, type, size: type === "file" ? Number(m[4]) : 0, linkTarget });
  }
  return entries;
}

export function parseListing(kind: ArchiveKind, out: string): ArchiveEntry[] {
  if (kind === "zip") return parseZipinfo(out);
  if (kind === "tar") return parseGnuTar(out);
  return parseBsdtar(out);
}

// ---------------------------------------------------------------------------
// Safety checks
// ---------------------------------------------------------------------------

/** Why an archive member name is unacceptable, or null if it is fine. */
export function unsafeName(name: string): string | null {
  if (typeof name !== "string" || name.length === 0) return "an empty file name";
  if (name.length > 4096) return "an over-long path";
  // eslint-disable-next-line no-control-regex
  if (/[\x00-\x1f\x7f]/.test(name)) return "a file name with control characters";
  if (name.startsWith("/") || name.startsWith("\\")) return "an absolute path";
  if (/^[A-Za-z]:/.test(name)) return "a drive-letter path";
  // Treat backslash as a separator too: Windows-made zips use it, and "..\\x"
  // must not slip past a "/"-only check.
  if (name.replace(/\\/g, "/").split("/").some((s) => s === "..")) return "a path that climbs out of the folder (..)";
  return null;
}

/** Collapse "." and empty segments; returns "" for the archive root. */
export function normEntryPath(name: string): string {
  return name.replace(/\\/g, "/").split("/").filter((s) => s !== "" && s !== ".").join("/");
}

/** Lexically resolve a relative symlink target against its link path; null if it leaves the root. */
export function symlinkStaysInside(linkPath: string, target: string): boolean {
  if (!target || target.startsWith("/") || target.startsWith("\\") || /^[A-Za-z]:/.test(target)) return false;
  // eslint-disable-next-line no-control-regex
  if (/[\x00-\x1f\x7f]/.test(target)) return false;
  const stack = normEntryPath(linkPath).split("/").filter(Boolean);
  stack.pop(); // the directory containing the link
  for (const seg of target.replace(/\\/g, "/").split("/")) {
    if (seg === "" || seg === ".") continue;
    if (seg === "..") { if (stack.length === 0) return false; stack.pop(); }
    else stack.push(seg);
  }
  return true;
}

export type CheckOptions = {
  kind: ArchiveKind;
  archiveBytes: number;
  availBytes: number | null;
  maxBytes?: number;
  maxFiles?: number;
};
export type CheckResult =
  | { ok: true; totalBytes: number; fileCount: number; dirCount: number; linkCount: number }
  | { ok: false; error: string };

export const fmtMB = (n: number) =>
  n >= 1024 ** 3 ? `${(n / 1024 ** 3).toFixed(1)} GB` : `${Math.max(1, Math.round(n / 1024 ** 2))} MB`;

/** Decide whether a parsed listing is safe and within limits. Pure. */
export function checkListing(entries: ArchiveEntry[], opts: CheckOptions): CheckResult {
  const maxBytes = opts.maxBytes ?? MAX_EXTRACT_BYTES;
  const maxFiles = opts.maxFiles ?? MAX_EXTRACT_FILES;
  if (entries.length === 0) return { ok: false, error: "This archive is empty." };
  if (entries.length > maxFiles) {
    return { ok: false, error: `This archive has more than ${maxFiles.toLocaleString("en-US")} entries, which is over the extraction limit.` };
  }

  let total = 0, files = 0, dirs = 0, links = 0;
  const symlinks = new Set<string>();
  for (const e of entries) {
    const bad = unsafeName(e.path);
    if (bad) return { ok: false, error: `Refusing to extract: the archive contains ${bad} (“${e.path.slice(0, 80).replace(/[^\x20-\x7e]/g, "?")}”).` };
    const p = normEntryPath(e.path);
    if (e.type === "hardlink") return { ok: false, error: "Refusing to extract: the archive contains hard links." };
    if (e.type === "special") return { ok: false, error: "Refusing to extract: the archive contains device or pipe entries." };
    if (e.type === "symlink") {
      if (opts.kind === "zip") return { ok: false, error: "Refusing to extract: .zip archives with symbolic links are not supported. Repack without links, or use .tar.gz." };
      if (e.linkTarget === undefined || !symlinkStaysInside(p, e.linkTarget)) {
        return { ok: false, error: "Refusing to extract: the archive contains a symbolic link that points outside its own folder." };
      }
      symlinks.add(p);
      links++;
      continue;
    }
    if (e.type === "dir") { dirs++; continue; }
    files++;
    total += e.size;
  }
  // Writing THROUGH a symlink the archive itself planted is the classic escape.
  if (symlinks.size) {
    for (const e of entries) {
      const segs = normEntryPath(e.path).split("/");
      for (let i = 1; i < segs.length; i++) {
        if (symlinks.has(segs.slice(0, i).join("/"))) {
          return { ok: false, error: "Refusing to extract: the archive writes files through a symbolic link." };
        }
      }
    }
  }
  if (total > maxBytes) {
    return { ok: false, error: `This archive would unpack to ${fmtMB(total)}, over the ${fmtMB(maxBytes)} extraction limit.` };
  }
  if (total > RATIO_MIN_BYTES && opts.archiveBytes > 0 && total / opts.archiveBytes > MAX_RATIO) {
    return { ok: false, error: "Refusing to extract: the compression ratio is implausibly high (possible zip bomb)." };
  }
  if (opts.availBytes !== null && total + MIN_FREE_MARGIN_BYTES > opts.availBytes) {
    return {
      ok: false,
      error: `Not enough free disk space: the archive needs about ${fmtMB(total)} and the server has ${fmtMB(Math.max(0, opts.availBytes))} free (a ${fmtMB(MIN_FREE_MARGIN_BYTES)} safety margin is kept).`,
    };
  }
  return { ok: true, totalBytes: total, fileCount: files, dirCount: dirs, linkCount: links };
}

/** Allow-list for paths we hand to the guest (always shell-quoted as well). */
export function checkGuestPath(p: string, what: string): string {
  // eslint-disable-next-line no-control-regex
  if (typeof p !== "string" || !p.startsWith("/") || /[\x00-\x1f\x7f]/.test(p)) throw new Error(`Invalid ${what}.`);
  if (/^\/(proc|sys|dev)(\/|$)/.test(p)) throw new Error(`Invalid ${what}.`);
  return p;
}

// ---------------------------------------------------------------------------
// Output parsing for the guest script
// ---------------------------------------------------------------------------

export type Probe = { tools: Record<string, boolean>; archiveOk: boolean; targetNotDir: boolean; availBytes: number | null; archiveBytes: number };

export function parseProbe(out: string): Probe {
  const p: Probe = { tools: {}, archiveOk: false, targetNotDir: false, availBytes: null, archiveBytes: 0 };
  for (const line of out.split("\n")) {
    const [k, a, b] = line.trim().split(/\s+/);
    if (k === "TOOL") p.tools[a] = b === "1";
    else if (k === "ARCHIVE_OK") p.archiveOk = a === "1";
    else if (k === "TARGET_NOTDIR") p.targetNotDir = a === "1";
    else if (k === "AVAIL_KB" && /^\d+$/.test(a ?? "")) p.availBytes = Number(a) * 1024;
    else if (k === "ARCHIVE_BYTES" && /^\d+$/.test(a ?? "")) p.archiveBytes = Number(a);
  }
  return p;
}

export type ListOutput = { text: string; rc: number | null; truncated: boolean };

export function parseListOutput(out: string): ListOutput {
  const idx = out.lastIndexOf("\nNXLIST_RC ");
  if (idx < 0) return { text: out, rc: null, truncated: out.length >= MAX_LISTING_BYTES };
  const rcRaw = out.slice(idx + 11).trim();
  const text = out.slice(0, idx);
  return { text, rc: /^\d+$/.test(rcRaw) ? Number(rcRaw) : null, truncated: text.length >= MAX_LISTING_BYTES - 1 };
}

export type ExtractOutput =
  | { ok: true; extracted: number; skippedExisting: number; skippedUnsafe: number; dirs: number; bytes: number }
  | { ok: false; error: string };

export function parseExtractOutput(out: string): ExtractOutput {
  const err = /^NXERR (.*)$/m.exec(out);
  if (err) return { ok: false, error: err[1].slice(0, 400) };
  const m = /^NXRESULT extracted=(\d+) skipped=(\d+) unsafe=(\d+) dirs=(\d+) bytes=(\d+)$/m.exec(out);
  if (!m) return { ok: false, error: "Extraction did not report a result. The server may have run out of resources — please try again." };
  return { ok: true, extracted: +m[1], skippedExisting: +m[2], skippedUnsafe: +m[3], dirs: +m[4], bytes: +m[5] };
}

// ---------------------------------------------------------------------------
// The guest-side script (fed to `bash -s -- <mode> <args…>` over STDIN).
// `@{` is `${` — String.raw cannot hold a literal `${` without interpolating.
// ---------------------------------------------------------------------------

export const GUEST_SCRIPT = String.raw`
set -u
umask 022
export LC_ALL=C
MODE="$1"

if [ "$MODE" = probe ]; then
  ARCHIVE="$2"; TARGET="$3"
  for t in unzip tar bsdtar gzip bzip2 xz timeout; do
    if command -v "$t" >/dev/null 2>&1; then echo "TOOL $t 1"; else echo "TOOL $t 0"; fi
  done
  if [ -f "$ARCHIVE" ]; then echo "ARCHIVE_OK 1"; echo "ARCHIVE_BYTES $(stat -c %s -- "$ARCHIVE")"; else echo "ARCHIVE_OK 0"; fi
  if [ -e "$TARGET" ] && [ ! -d "$TARGET" ]; then echo "TARGET_NOTDIR 1"; fi
  d="$TARGET"
  while [ ! -d "$d" ] && [ "$d" != / ]; do d=$(dirname -- "$d"); done
  echo "AVAIL_KB $(df -Pk -- "$d" | awk 'NR==2{print $4}')"
  exit 0
fi

if [ "$MODE" = list ]; then
  KIND="$2"; ARCHIVE="$3"; ERR=$(mktemp)
  case "$KIND" in
    zip) timeout 90 unzip -Z -l -- "$ARCHIVE" 2>"$ERR" ;;
    tar) timeout 90 tar -tvf "$ARCHIVE" 2>"$ERR" ;;
    *)   timeout 90 bsdtar -tvf "$ARCHIVE" 2>"$ERR" ;;
  esac | head -c 8000000
  rc=@{PIPESTATUS[0]}
  printf '\nNXLIST_RC %s\n' "$rc"
  rm -f -- "$ERR"
  exit 0
fi

# ---- extract ---------------------------------------------------------------
KIND="$2"; ARCHIVE="$3"; TARGET="$4"; OVERWRITE="$5"; MAXBYTES="$6"; MAXFILES="$7"; TLIMIT="$8"
STAGE=""; LOG=""; SKIPDIRS=""
cleanup() {
  [ -n "$STAGE" ] && { chmod -R u+rwX -- "$STAGE" 2>/dev/null; rm -rf -- "$STAGE"; }
  [ -n "$LOG" ] && rm -f -- "$LOG"
  [ -n "$SKIPDIRS" ] && rm -f -- "$SKIPDIRS"
}
trap cleanup EXIT HUP INT TERM
fail() { printf 'NXERR %s\n' "$1"; exit 0; }

[ -f "$ARCHIVE" ] || fail "The archive could not be found."
mkdir -p -- "$TARGET" 2>/dev/null || fail "Could not create the target folder."
[ -d "$TARGET" ] || fail "The target is not a folder."
TARGET_REAL=$(readlink -f -- "$TARGET") || fail "Could not resolve the target folder."
STAGE=$(mktemp -d "$TARGET_REAL/.nxeon-extract.XXXXXX") || fail "Could not create a working folder (is the disk full or the folder read-only?)."
LOG=$(mktemp) || fail "Could not create a temp file."
SKIPDIRS=$(mktemp) || fail "Could not create a temp file."
STAGE_REAL=$(readlink -f -- "$STAGE")

BLOCKS=$((MAXBYTES / 512 + 1))
(
  ulimit -f "$BLOCKS" 2>/dev/null
  case "$KIND" in
    zip) exec timeout -k 5 "$TLIMIT" unzip -qq -o -d "$STAGE" -- "$ARCHIVE" ;;
    tar) exec timeout -k 5 "$TLIMIT" tar -xf "$ARCHIVE" -C "$STAGE" --no-same-owner --no-same-permissions ;;
    *)   exec timeout -k 5 "$TLIMIT" bsdtar -xf "$ARCHIVE" -C "$STAGE" --no-same-owner --no-same-permissions ;;
  esac
) </dev/null >"$LOG" 2>&1 &
PID=$!

ABORT=""
while kill -0 "$PID" 2>/dev/null; do
  sleep 1
  used=$(du -sb -- "$STAGE" 2>/dev/null | cut -f1)
  if [ "$used" -gt "$MAXBYTES" ] 2>/dev/null; then ABORT="size"; kill "$PID" 2>/dev/null; break; fi
  cnt=$(find "$STAGE" -mindepth 1 2>/dev/null | head -n "$((MAXFILES + 1))" | wc -l)
  if [ "$cnt" -gt "$MAXFILES" ]; then ABORT="files"; kill "$PID" 2>/dev/null; break; fi
done
wait "$PID" 2>/dev/null
RC=$?

[ "$ABORT" = size ] && fail "Extraction stopped: the archive unpacked to more data than its listing claimed (over the size limit). Nothing was written."
[ "$ABORT" = files ] && fail "Extraction stopped: the archive contains more files than its listing claimed. Nothing was written."
[ "$RC" -eq 124 ] || [ "$RC" -eq 137 ] && fail "Extraction took too long and was stopped. Nothing was written."
[ "$RC" -eq 153 ] && fail "A file in the archive is larger than the size limit. Nothing was written."
if [ "$RC" -ne 0 ] && ! { [ "$KIND" = zip ] && [ "$RC" -eq 1 ]; }; then
  fail "Extraction failed: $(tail -c 300 "$LOG" | tr -c '[:print:]' ' ' | tr -s ' ')"
fi

# ---- post-scan: do not trust the listing --------------------------------------
chmod -R u+rwX -- "$STAGE" 2>/dev/null
UNSAFE=0
n=$(find "$STAGE" -mindepth 1 ! -type f ! -type d ! -type l | wc -l)
UNSAFE=$((UNSAFE + n))
find "$STAGE" -mindepth 1 ! -type f ! -type d ! -type l -delete 2>/dev/null
while IFS= read -r -d '' l; do
  raw=$(readlink -- "$l" 2>/dev/null)
  res=$(readlink -f -- "$l" 2>/dev/null)
  case "$raw" in
    /*) rm -f -- "$l"; UNSAFE=$((UNSAFE + 1)); continue ;;
  esac
  case "$res" in
    "$STAGE_REAL"/*) ;;
    *) rm -f -- "$l"; UNSAFE=$((UNSAFE + 1)) ;;
  esac
done < <(find "$STAGE" -type l -print0)
n=$(find "$STAGE" -type f -links +1 | wc -l)
UNSAFE=$((UNSAFE + n))
find "$STAGE" -type f -links +1 -delete 2>/dev/null
find "$STAGE" -type f -perm /6000 -exec chmod ug-s -- {} + 2>/dev/null

read -r FILES BYTES < <(find "$STAGE" -type f -printf '%s\n' | awk '{n++; s+=$1} END{print n+0, s+0}')
[ "$BYTES" -le "$MAXBYTES" ] || fail "The extracted data exceeds the size limit. Nothing was written."

OWN=$(stat -c %u:%g -- "$TARGET_REAL")
if [ "$OWN" != "0:0" ]; then chown -R -h "$OWN" -- "$STAGE" 2>/dev/null; fi

# ---- merge into the target ----------------------------------------------------
EXTRACTED=0; SKIPPED=0; DIRS=0
cd "$STAGE_REAL" || fail "Could not enter the working folder."
under_skipped() {
  while IFS= read -r -d '' s; do
    case "$1" in "$s"/*) return 0 ;; esac
  done < "$SKIPDIRS"
  return 1
}
while IFS= read -r -d '' rel; do
  dst="$TARGET_REAL/$rel"
  if under_skipped "$rel"; then continue; fi
  if [ -L "$dst" ] || { [ -e "$dst" ] && [ ! -d "$dst" ]; }; then
    printf '%s\0' "$rel" >> "$SKIPDIRS"
    continue
  fi
  if [ ! -d "$dst" ]; then
    if mkdir -- "$dst" 2>/dev/null; then
      DIRS=$((DIRS + 1))
      chmod --reference="$rel" -- "$dst" 2>/dev/null
      chown --reference="$rel" -- "$dst" 2>/dev/null
    fi
  fi
done < <(find . -mindepth 1 -type d -printf '%P\0')
while IFS= read -r -d '' rel; do
  if under_skipped "$rel"; then SKIPPED=$((SKIPPED + 1)); continue; fi
  dst="$TARGET_REAL/$rel"
  if [ -e "$dst" ] || [ -L "$dst" ]; then
    if [ "$OVERWRITE" != 1 ]; then SKIPPED=$((SKIPPED + 1)); continue; fi
    if [ -d "$dst" ] && [ ! -L "$dst" ]; then SKIPPED=$((SKIPPED + 1)); continue; fi
  fi
  if mv -f -T -- "$rel" "$dst" 2>/dev/null; then EXTRACTED=$((EXTRACTED + 1)); else SKIPPED=$((SKIPPED + 1)); fi
done < <(find . -mindepth 1 \( -type f -o -type l \) -printf '%P\0')

printf 'NXRESULT extracted=%s skipped=%s unsafe=%s dirs=%s bytes=%s\n' "$EXTRACTED" "$SKIPPED" "$UNSAFE" "$DIRS" "$BYTES"
`.replaceAll("@{", "${");

