test("detectArchive recognises every supported extension, case-insensitively", () => {
  const cases: Array<[string, string, string | null, string]> = [
    ["mods.zip", "zip", null, "mods"], ["a.tar", "tar", null, "a"], ["a.tar.gz", "tar", "gz", "a"],
    ["a.TGZ", "tar", "gz", "a"], ["a.tar.bz2", "tar", "bz2", "a"], ["a.tbz2", "tar", "bz2", "a"],
    ["a.tar.xz", "tar", "xz", "a"], ["a.txz", "tar", "xz", "a"], ["a.7z", "7z", null, "a"],
    ["My Mod (1).RAR", "rar", null, "My Mod (1)"], ["/x/y/z.zip", "zip", null, "z"],
  ];
  for (const [n, kind, comp, stem] of cases) {
    const d = detectArchive(n);
    assert.ok(d, n);
    assert.equal(d.kind, kind); assert.equal(d.compression, comp); assert.equal(d.stem, stem);
  }
  for (const n of ["a.txt", "zip", ".zip", "a.gz", "a.jar", "a.zip.bak", "a.tar.gz.txt"]) assert.equal(detectArchive(n), null, n);
});

