  assert.deepEqual(requiredTools(detectArchive("a.tar.xz")!), ["timeout", "tar", "xz"]);
  assert.deepEqual(requiredTools(detectArchive("a.rar")!), ["timeout", "bsdtar"]);
  assert.equal(packageFor("apt", "xz"), "xz-utils");
  assert.equal(packageFor("dnf", "bsdtar"), "bsdtar");
  assert.equal(packageFor("apt", "bsdtar"), "libarchive-tools");
  assert.equal(packageFor("apt", "timeout"), null);
  assert.equal(pmFromPrefix("DEBIAN_FRONTEND=noninteractive apt-get install -y"), "apt");
  assert.equal(pmFromPrefix("dnf install -y"), "dnf");
  assert.equal(pmFromPrefix("yum install -y"), "yum");
});

test("unsafeName rejects zip-slip, absolute, drive, control chars", () => {
  for (const bad of ["../x", "a/../../b", "..", "a/..", "/etc/passwd", "\\evil", "..\\..\\x", "a\\..\\..\\x", "C:/Windows/x", "a\nb", "a\0b", "", "x/".repeat(3000)]) {
    assert.ok(unsafeName(bad), JSON.stringify(bad.slice(0, 20)));
  }
  for (const ok of ["a.txt", "./a", "dir/sub/file.jar", "a..b", "..a/b", "My Mod (1)/x y.dll", "a/./b"]) assert.equal(unsafeName(ok), null, ok);
});

test("normEntryPath / symlinkStaysInside", () => {
  assert.equal(normEntryPath("./a//b/./c/"), "a/b/c");
  assert.equal(normEntryPath("./"), "");
  assert.ok(symlinkStaysInside("a/ln", "b/c"));
  assert.ok(symlinkStaysInside("a/b/ln", "../c"));
  assert.ok(symlinkStaysInside("ln", "dir/c"));
  assert.ok(!symlinkStaysInside("ln", "../x"));
  assert.ok(!symlinkStaysInside("a/ln", "../../x"));
  assert.ok(!symlinkStaysInside("ln", "/etc/passwd"));
  assert.ok(!symlinkStaysInside("ln", ""));
  assert.ok(!symlinkStaysInside("a/ln", "b/../../../x"));
