test("parseZipinfo", () => {
  const out = [
    "Archive:  t.zip", "Zip file size: 211 bytes, number of entries: 2",
    "-rw-r--r--  2.0 unx        3 b-        3 stor 26-Oct-01 13:12 a b.txt",
    "drwxr-xr-x  2.0 unx        0 b-        0 stor 26-Oct-01 13:12 dir/",
    "-rw-a--     2.0 fat      100 b-       50 defN 2026-10-01 13:12 win/x.dll",
    "3 files, 103 bytes uncompressed, 53 bytes compressed:  0.0%", "",
  ].join("\n");
  const e = parseZipinfo(out);
  assert.deepEqual(e.map((x) => [x.path, x.type, x.size]), [["a b.txt", "file", 3], ["dir/", "dir", 0], ["win/x.dll", "file", 100]]);
  assert.throws(() => parseZipinfo(out.replace("3 files", "4 files")), /damaged/);
  assert.throws(() => parseZipinfo("garbage\n"), /damaged/);
  assert.throws(() => parseZipinfo("Archive: x\n"), /damaged/);
  // a newline smuggled into a name yields an unparseable line -> refused, not mis-read
  assert.throws(() => parseZipinfo(out.replace("a b.txt", "a\n../../evil")), /damaged/);
  assert.equal(parseZipinfo("Archive: x\nEmpty zipfile.\n").length, 0);
  assert.equal(parseZipinfo("-rwxrwxrwx  2.0 unx 1 b- 1 stor 26-Oct-01 13:12 x\n1 file, 1 bytes uncompressed, 1 bytes compressed: 0%\n")[0].type, "file");
  assert.equal(parseZipinfo("lrwxrwxrwx  2.0 unx 5 b- 5 stor 26-Oct-01 13:12 ln\n1 file, 5 bytes uncompressed, 5 bytes compressed: 0%\n")[0].type, "symlink");
});

test("parseGnuTar incl. links and devices", () => {
  const out = [
    "drwxr-xr-x root/root         0 2026-10-01 13:12 ./",
    "lrwxrwxrwx root/root         0 2026-10-01 13:12 ./abs -> /etc/passwd",
    "-rw-r--r-- 1000/1000         3 2026-10-01 13:12 ./a b.txt",
    "hrw-r--r-- root/root         0 2026-10-01 13:12 ./hl link to ./a b.txt",
    "crw-r--r-- root/root       1,3 2026-10-01 13:12 ./dev/null",
  ].join("\n");
  const e = parseGnuTar(out);
  assert.deepEqual(e.map((x) => x.type), ["dir", "symlink", "file", "hardlink", "special"]);
  assert.equal(e[1].linkTarget, "/etc/passwd");
  assert.equal(e[1].path, "./abs");
  assert.equal(e[3].linkTarget, "./a b.txt");
  assert.equal(e[2].size, 3);
  assert.throws(() => parseGnuTar("nonsense"), /damaged/);
});

test("parseBsdtar", () => {
