// ---------------------------------------------------------------------------
// Integration: run the REAL guest script against real archives in a temp dir.
// Needs unzip, tar, bsdtar, python3 on PATH (NXEON_XT_PATH may prepend dirs).
// ---------------------------------------------------------------------------
const extraPath = process.env.NXEON_XT_PATH ?? "";
const env = { ...process.env, PATH: `${extraPath}${extraPath ? ":" : ""}${process.env.PATH}` };
const have = (t: string) => spawnSync("bash", ["-c", `command -v ${t}`], { env }).status === 0;
const toolsOk = have("unzip") && have("tar") && have("bsdtar") && have("python3") && have("timeout");
const it = toolsOk ? test : test.skip;

function runScript(...args: string[]) {
  const r = spawnSync("bash", ["-s", "--", ...args], { input: GUEST_SCRIPT, env, encoding: "utf8", timeout: 120_000 });
  return r.stdout + r.stderr;
}
function listOf(kind: string, archive: string) {
  const o = parseListOutput(runScript("list", kind, archive));
  assert.equal(o.rc, 0, o.text);
  return parseListing(kind === "zip" ? "zip" : kind === "tar" ? "tar" : "7z", o.text);
}
function sandbox() {
  const root = mkdtempSync(join(tmpdir(), "xt-"));
  const src = join(root, "src"); mkdirSync(src);
  return { root, src, target: join(root, "target"), done: () => rmSync(root, { recursive: true, force: true }) };
}
const py = (code: string, cwd: string) => { const r = spawnSync("python3", ["-c", code], { cwd }); assert.equal(r.status, 0, String(r.stderr)); };
const extract = (kind: string, arc: string, target: string, over = 0, maxBytes = 1e9, maxFiles = 1000, t = 60) =>
  parseExtractOutput(runScript("extract", kind, arc, target, String(over), String(maxBytes), String(maxFiles), String(t)));
const leftovers = (dir: string) => readdirSync(dir).filter((n) => n.startsWith(".nxeon-extract"));

it("extracts a normal zip, tgz, txz, tar, preserving names with spaces; no staging litter", () => {
  const s = sandbox();
  try {
    writeFileSync(join(s.src, "a b.txt"), "hello");
    mkdirSync(join(s.src, "dir/sub"), { recursive: true });
    writeFileSync(join(s.src, "dir/sub/c.txt"), "deep");
    py("import zipfile;z=zipfile.ZipFile('../t.zip','w');z.write('a b.txt');z.write('dir/sub/c.txt');z.close()", s.src);
    spawnSync("tar", ["czf", "../t.tgz", "."], { cwd: s.src });
    spawnSync("tar", ["cJf", "../t.txz", "."], { cwd: s.src });
    spawnSync("tar", ["cf", "../t.tar", "."], { cwd: s.src });
    for (const [kind, file] of [["zip", "t.zip"], ["tar", "t.tgz"], ["tar", "t.txz"], ["tar", "t.tar"]] as const) {
      const target = join(s.root, `out-${file}`);
      const arc = join(s.root, file);
      const entries = listOf(kind, arc);
      assert.ok(checkListing(entries, { kind, archiveBytes: 100, availBytes: null }).ok, file);
      const r = extract(kind, arc, target);
      assert.ok(r.ok, JSON.stringify(r));
      if (r.ok) { assert.equal(r.extracted, 2); assert.equal(r.skippedUnsafe, 0); }
      assert.equal(readFileSync(join(target, "a b.txt"), "utf8"), "hello");
      assert.equal(readFileSync(join(target, "dir/sub/c.txt"), "utf8"), "deep");
      assert.deepEqual(leftovers(target), []);
    }
  } finally { s.done(); }
});

it("7z through bsdtar", () => {
  const s = sandbox();
  try {
    writeFileSync(join(s.src, "m.dll"), "mod");
    // bsdtar can write 7z; reading it back exercises the same path as a customer .7z
    const w = spawnSync("bsdtar", ["--format", "7zip", "-cf", "../t.7z", "m.dll"], { cwd: s.src, env });
    assert.equal(w.status, 0, String(w.stderr));
    const arc = join(s.root, "t.7z");
    assert.ok(checkListing(listOf("7z", arc), { kind: "7z", archiveBytes: 100, availBytes: null }).ok);
    const r = extract("7z", arc, s.target);
    assert.ok(r.ok && r.extracted === 1, JSON.stringify(r));
    assert.equal(readFileSync(join(s.target, "m.dll"), "utf8"), "mod");
  } finally { s.done(); }
});

it("no overwrite by default; overwrite on request; existing dirs merge", () => {
  const s = sandbox();
  try {
    writeFileSync(join(s.src, "a.txt"), "NEW"); writeFileSync(join(s.src, "b.txt"), "NEWB");
    spawnSync("tar", ["cf", "../t.tar", "a.txt", "b.txt"], { cwd: s.src });
    mkdirSync(s.target); writeFileSync(join(s.target, "a.txt"), "OLD");
    const arc = join(s.root, "t.tar");
    const r1 = extract("tar", arc, s.target);
    assert.ok(r1.ok && r1.extracted === 1 && r1.skippedExisting === 1, JSON.stringify(r1));
    assert.equal(readFileSync(join(s.target, "a.txt"), "utf8"), "OLD");
    assert.equal(readFileSync(join(s.target, "b.txt"), "utf8"), "NEWB");
    const r2 = extract("tar", arc, s.target, 1);
    assert.ok(r2.ok && r2.extracted === 2 && r2.skippedExisting === 0, JSON.stringify(r2));
    assert.equal(readFileSync(join(s.target, "a.txt"), "utf8"), "NEW");
  } finally { s.done(); }
});

it("MALICIOUS zip-slip zip: listing check refuses it, and nothing escapes even if forced", () => {
  const s = sandbox();
  try {
    py(
      "import zipfile;z=zipfile.ZipFile('../evil.zip','w');z.writestr('ok.txt','ok');" +
        "z.writestr('../escaped.txt','pwn');z.writestr('../../escaped2.txt','pwn');z.writestr('/tmp/xt-abs-escape.txt','pwn');z.close()",
      s.src
    );
    const arc = join(s.root, "evil.zip");
    const entries = listOf("zip", arc);
    const chk = checkListing(entries, { kind: "zip", archiveBytes: 100, availBytes: null });
    assert.equal(chk.ok, false);
    // Defence in depth: bypass the TS check and run the extractor anyway.
    const inner = join(s.root, "inner"); mkdirSync(inner);
    const r = extract("zip", arc, join(inner, "target"));
    assert.ok(r.ok, JSON.stringify(r));
    assert.ok(!existsSync(join(inner, "escaped.txt")));
    assert.ok(!existsSync(join(s.root, "escaped.txt")));
    assert.ok(!existsSync(join(s.root, "escaped2.txt")));
    assert.ok(!existsSync("/tmp/xt-abs-escape.txt"));
    assert.ok(existsSync(join(inner, "target", "ok.txt")));
  } finally { s.done(); rmSync("/tmp/xt-abs-escape.txt", { force: true }); }
});

it("MALICIOUS tar: ../ member, absolute member, symlink escape + write-through, hardlink, fifo", () => {
  const s = sandbox();
  try {
    py(
      `
import tarfile, io
def mk(name, build):
    t = tarfile.open('../'+name, 'w')
    build(t); t.close()
def add(t, n, data=b'x', typ=tarfile.REGTYPE, link=None):
    i = tarfile.TarInfo(n); i.type = typ; i.size = len(data) if typ == tarfile.REGTYPE else 0
    if link: i.linkname = link
    t.addfile(i, io.BytesIO(data) if typ == tarfile.REGTYPE else None)
mk('slip.tar', lambda t: (add(t,'ok.txt'), add(t,'../escaped.txt'), add(t,'/tmp/xt-abs-escape2.txt')))
mk('symlink.tar', lambda t: (add(t,'ln',typ=tarfile.SYMTYPE,link='/etc'), add(t,'ln/xt-pwn.txt')))
mk('relsym.tar', lambda t: (add(t,'ln',typ=tarfile.SYMTYPE,link='../../..'), add(t,'ok.txt')))
mk('hard.tar', lambda t: (add(t,'h',typ=tarfile.LNKTYPE,link='/etc/passwd'),))
mk('fifo.tar', lambda t: (add(t,'p',typ=tarfile.FIFOTYPE),))
`,
      s.src
    );
    for (const name of ["slip", "symlink", "relsym", "hard", "fifo"]) {
      const arc = join(s.root, `${name}.tar`);
      const chk = checkListing(listOf("tar", arc), { kind: "tar", archiveBytes: 100, availBytes: null });
      assert.equal(chk.ok, false, `${name} must be refused by the listing check`);
    }
    // Defence in depth: run the extractor on the link tars anyway.
    for (const name of ["symlink", "relsym", "hard", "fifo", "slip"]) {
      const inner = join(s.root, `in-${name}`); mkdirSync(inner);
      const r = extract("tar", join(s.root, `${name}.tar`), join(inner, "t"));
      assert.ok(!existsSync("/etc/xt-pwn.txt"), name);
      assert.ok(!existsSync(join(inner, "escaped.txt")), name);
      assert.ok(!existsSync("/tmp/xt-abs-escape2.txt"), name);
      if (r.ok && existsSync(join(inner, "t"))) {
        // any symlink that survived must stay inside the target
        const walk = (d: string): void => { for (const n of readdirSync(d)) { const p = join(d, n); const st = lstatSync(p);
          assert.ok(!st.isSymbolicLink(), `${name}: escaping symlink survived`); assert.ok(st.isFile() || st.isDirectory(), `${name}: special file survived`);
          if (st.isDirectory()) walk(p); } };
        walk(join(inner, "t"));
      }
    }
  } finally { s.done(); rmSync("/tmp/xt-abs-escape2.txt", { force: true }); }
});

it("safe relative symlink inside the archive is kept; pre-existing symlinked dir in target is not followed", () => {
  const s = sandbox();
  try {
    mkdirSync(join(s.src, "sub"));
    writeFileSync(join(s.src, "sub/x.txt"), "x");
    symlinkSync("sub/x.txt", join(s.src, "ln"));
    spawnSync("tar", ["cf", "../t.tar", "sub", "ln"], { cwd: s.src });
    const arc = join(s.root, "t.tar");
    assert.ok(checkListing(listOf("tar", arc), { kind: "tar", archiveBytes: 100, availBytes: null }).ok);
    const r = extract("tar", arc, s.target);
    assert.ok(r.ok && r.extracted === 2, JSON.stringify(r));
    assert.ok(lstatSync(join(s.target, "ln")).isSymbolicLink());
    // now a target where `sub` is a symlink to an outside dir
    const outside = join(s.root, "outside"); mkdirSync(outside);
    const t2 = join(s.root, "t2"); mkdirSync(t2); symlinkSync(outside, join(t2, "sub"));
    const r2 = extract("tar", arc, t2);
    assert.ok(r2.ok, JSON.stringify(r2));
    assert.deepEqual(readdirSync(outside), [], "must not write through a pre-existing symlinked directory");
  } finally { s.done(); }
});

it("BOMB: size cap enforced during extraction even when the listing lied", () => {
  const s = sandbox();
  try {
    // 60 MB of zeros compresses to ~60 KB; run with a 10 MB cap (as if the listing had under-reported).
    py("import zipfile;z=zipfile.ZipFile('../bomb.zip','w',zipfile.ZIP_DEFLATED);z.writestr('zeros.bin',b'\\0'*(60*1024*1024));z.close()", s.src);
    const arc = join(s.root, "bomb.zip");
    // the TS check catches it from the listing under a small cap...
    const chk = checkListing(listOf("zip", arc), { kind: "zip", archiveBytes: 70_000, availBytes: null, maxBytes: 10 * 1024 ** 2 });
    assert.equal(chk.ok, false);
    // ...and the guest script stops it independently.
    const r = extract("zip", arc, s.target, 0, 10 * 1024 ** 2);
    assert.equal(r.ok, false, JSON.stringify(r));
    assert.ok(!r.ok && /size limit|larger than/.test(r.error), JSON.stringify(r));
    assert.deepEqual(existsSync(s.target) ? readdirSync(s.target) : [], [], "nothing merged, staging cleaned");
  } finally { s.done(); }
});

