it("time cap stops a slow extraction", () => {
  // Not easily forced with real archives; verify the timeout wiring: 1s limit on a big-ish tar.
  const s = sandbox();
  try {
    py("import zipfile;z=zipfile.ZipFile('../b.zip','w',zipfile.ZIP_DEFLATED);z.writestr('z.bin',b'\\0'*(900*1024*1024));z.close()", s.src);
    const t0 = Date.now();
    const r = extract("zip", join(s.root, "b.zip"), s.target, 0, 2 * 1024 ** 3, 1000, 1);
    // either it finished in <1s (fast disk) or was stopped; it must never hang
    assert.ok(Date.now() - t0 < 60_000);
    if (!r.ok) assert.ok(/too long|Nothing was written/.test(r.error), JSON.stringify(r));
  } finally { s.done(); }
});

