test("checkListing: limits", () => {
  assert.equal(checkListing([], opts).ok, false);
  assert.equal(checkListing([f("a", 1), f("b", 2)], opts).ok, true);
  const r = checkListing([f("a", 10), { path: "d/", type: "dir", size: 0 }], opts);
  assert.ok(r.ok && r.totalBytes === 10 && r.fileCount === 1 && r.dirCount === 1);
  assert.equal(checkListing([f("big", MAX_EXTRACT_BYTES + 1)], { ...opts, archiveBytes: MAX_EXTRACT_BYTES }).ok, false);
  assert.equal(checkListing([f("a"), f("b"), f("c")], { ...opts, maxFiles: 2 }).ok, false);
  // zip bomb: 500 MB from a 100 KB archive
  const bomb = checkListing([f("zeros", 500 * 1024 ** 2)], { ...opts, archiveBytes: 100 * 1024 });
  assert.ok(!bomb.ok && /bomb|ratio/i.test(bomb.error));
  // same size, sane ratio is fine
  assert.equal(checkListing([f("x", 500 * 1024 ** 2)], { ...opts, archiveBytes: 100 * 1024 ** 2 }).ok, true);
  // disk space
  const need = 500 * 1024 ** 2;
  assert.equal(checkListing([f("x", need)], { ...opts, archiveBytes: need, availBytes: need + MIN_FREE_MARGIN_BYTES }).ok, true);
  const low = checkListing([f("x", need)], { ...opts, archiveBytes: need, availBytes: need + MIN_FREE_MARGIN_BYTES - 1 });
  assert.ok(!low.ok && /free disk/.test(low.error));
  assert.equal(checkListing([f("x", need)], { ...opts, archiveBytes: need, availBytes: null }).ok, true);
});

