// ---------------------------------------------------------------------------
// Integration: run the REAL guest script against real archives in a temp dir.
// Needs unzip, tar, bsdtar, python3 on PATH (NXEON_XT_PATH may prepend dirs).
// ---------------------------------------------------------------------------
const extraPath = process.env.NXEON_XT_PATH ?? "";
const env = { ...process.env, PATH: `${extraPath}${extraPath ? ":" : ""}${process.env.PATH}` };
const have = (t: string) => spawnSync("bash", ["-c", `command -v ${t}`], { env }).status === 0;
const toolsOk = have("unzip") && have("tar") && have("bsdtar") && have("python3") && have("timeout");
const it = toolsOk ? test : test.skip;

function runScript(...args: string[]) {
  const r = spawnSync("bash", ["-s", "--", ...args], { input: GUEST_SCRIPT, env, encoding: "utf8", timeout: 120_000 });
  return r.stdout + r.stderr;
}
function listOf(kind: string, archive: string) {
  const o = parseListOutput(runScript("list", kind, archive));
  assert.equal(o.rc, 0, o.text);
  return parseListing(kind === "zip" ? "zip" : kind === "tar" ? "tar" : "7z", o.text);
}
function sandbox() {
  const root = mkdtempSync(join(tmpdir(), "xt-"));
  const src = join(root, "src"); mkdirSync(src);
  return { root, src, target: join(root, "target"), done: () => rmSync(root, { recursive: true, force: true }) };
}
const py = (code: string, cwd: string) => { const r = spawnSync("python3", ["-c", code], { cwd }); assert.equal(r.status, 0, String(r.stderr)); };
const extract = (kind: string, arc: string, target: string, over = 0, maxBytes = 1e9, maxFiles = 1000, t = 60) =>
  parseExtractOutput(runScript("extract", kind, arc, target, String(over), String(maxBytes), String(maxFiles), String(t)));
const leftovers = (dir: string) => readdirSync(dir).filter((n) => n.startsWith(".nxeon-extract"));

it("extracts a normal zip, tgz, txz, tar, preserving names with spaces; no staging litter", () => {
  const s = sandbox();
  try {
    writeFileSync(join(s.src, "a b.txt"), "hello");
    mkdirSync(join(s.src, "dir/sub"), { recursive: true });
    writeFileSync(join(s.src, "dir/sub/c.txt"), "deep");
    py("import zipfile;z=zipfile.ZipFile('../t.zip','w');z.write('a b.txt');z.write('dir/sub/c.txt');z.close()", s.src);
    spawnSync("tar", ["czf", "../t.tgz", "."], { cwd: s.src });
    spawnSync("tar", ["cJf", "../t.txz", "."], { cwd: s.src });
    spawnSync("tar", ["cf", "../t.tar", "."], { cwd: s.src });
    for (const [kind, file] of [["zip", "t.zip"], ["tar", "t.tgz"], ["tar", "t.txz"], ["tar", "t.tar"]] as const) {
      const target = join(s.root, `out-${file}`);
      const arc = join(s.root, file);
      const entries = listOf(kind, arc);
      assert.ok(checkListing(entries, { kind, archiveBytes: 100, availBytes: null }).ok, file);
      const r = extract(kind, arc, target);
      assert.ok(r.ok, JSON.stringify(r));
      if (r.ok) { assert.equal(r.extracted, 2); assert.equal(r.skippedUnsafe, 0); }
      assert.equal(readFileSync(join(target, "a b.txt"), "utf8"), "hello");
      assert.equal(readFileSync(join(target, "dir/sub/c.txt"), "utf8"), "deep");
      assert.deepEqual(leftovers(target), []);
    }
  } finally { s.done(); }
});

