it("MALICIOUS tar: ../ member, absolute member, symlink escape + write-through, hardlink, fifo", () => {
  const s = sandbox();
  try {
    py(
      `
import tarfile, io
def mk(name, build):
    t = tarfile.open('../'+name, 'w')
    build(t); t.close()
def add(t, n, data=b'x', typ=tarfile.REGTYPE, link=None):
    i = tarfile.TarInfo(n); i.type = typ; i.size = len(data) if typ == tarfile.REGTYPE else 0
    if link: i.linkname = link
    t.addfile(i, io.BytesIO(data) if typ == tarfile.REGTYPE else None)
mk('slip.tar', lambda t: (add(t,'ok.txt'), add(t,'../escaped.txt'), add(t,'/tmp/xt-abs-escape2.txt')))
mk('symlink.tar', lambda t: (add(t,'ln',typ=tarfile.SYMTYPE,link='/etc'), add(t,'ln/xt-pwn.txt')))
mk('relsym.tar', lambda t: (add(t,'ln',typ=tarfile.SYMTYPE,link='../../..'), add(t,'ok.txt')))
mk('hard.tar', lambda t: (add(t,'h',typ=tarfile.LNKTYPE,link='/etc/passwd'),))
mk('fifo.tar', lambda t: (add(t,'p',typ=tarfile.FIFOTYPE),))
`,
      s.src
    );
    for (const name of ["slip", "symlink", "relsym", "hard", "fifo"]) {
      const arc = join(s.root, `${name}.tar`);
      const chk = checkListing(listOf("tar", arc), { kind: "tar", archiveBytes: 100, availBytes: null });
      assert.equal(chk.ok, false, `${name} must be refused by the listing check`);
    }
    // Defence in depth: run the extractor on the link tars anyway.
    for (const name of ["symlink", "relsym", "hard", "fifo", "slip"]) {
      const inner = join(s.root, `in-${name}`); mkdirSync(inner);
