    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "extract", 8);
    if (limited) return { ok: false, error: limited };

    const archive = checkGuestPath(normalizePath(path), "archive path");
    const target = checkGuestPath(normalizePath(targetDir || "/"), "target folder");
    if (target === "/") return { ok: false, error: "Choose a folder to extract into — extracting straight into / is not allowed." };
    const info = detectArchive(archive);
    if (!info) {
