    }
    if (SANDBOX) return { ok: false, error: "Extraction isn't available in the sandbox preview." };
    if (extracting.has(serverId)) return { ok: false, error: "An extraction is already running on this server — wait for it to finish." };
    extracting.add(serverId);
    lockKey = serverId;

    const run = (conn: Parameters<Parameters<typeof withServerSsh>[1]>[0], timeoutMs: number, ...args: string[]) =>
      execInput(conn, `bash -s -- ${args.map(shellQuote).join(" ")}`, GUEST_SCRIPT, timeoutMs);

    const res = await withServerSsh(server, async (conn): Promise<ExtractResult> => {
      let probe = parseProbe((await run(conn, QUICK_TIMEOUT_MS, "probe", archive, target)).stdout);
      if (!probe.archiveOk) return { ok: false, error: "That archive could not be found on the server." };
      if (probe.targetNotDir) return { ok: false, error: "The target is a file, not a folder." };

      // Install any missing tool via the platform's package helper.
      const installed: string[] = [];
      const missing = requiredTools(info).filter((t) => !probe.tools[t]);
      if (missing.length) {
        let prefix: string;
        try {
          prefix = await pkgInstallPrefix(conn);
        } catch {
          return { ok: false, error: `This server is missing ${missing.join(", ")} and has no supported package manager to install it. Install it from the console, then try again.` };
        }
        const pm = pmFromPrefix(prefix);
        const pkgs = [...new Set(missing.map((t) => packageFor(pm, t)))];
        if (pkgs.some((p) => p === null)) {
          return { ok: false, error: `This server is missing ${missing.join(", ")}, which can't be installed automatically.` };
        }
        const list = (pkgs as string[]).join(" ");
        const cmd = pm === "apt"
          ? `${prefix} ${list} >/dev/null 2>&1 || (apt-get update -qq >/dev/null 2>&1 && ${prefix} ${list} >/dev/null 2>&1)`
          : `${prefix} ${list} >/dev/null 2>&1`;
        const inst = await withInstallTimeout(conn, cmd);
        probe = parseProbe((await run(conn, QUICK_TIMEOUT_MS, "probe", archive, target)).stdout);
